command:
set -eu
umask 077
: > /tmp/pgpass
printf '%s:*:*:%s:%s\n' 's' 'u' "$(sed -e 's/\\/\\\\/g' -e 's/:/\\:/g' /etc/pgcopydb/creds/source-mnt/source-password)" >> /tmp/pgpass
pf_esc() { printf '%s' "$1" | sed -e 's/\\/\\\\/g' -e 's/:/\\:/g'; }
db=$PGM_TARGET_DB
case "$db" in
postgresql://*|postgres://*)
  uri=$db
  rest=${uri#*://}; hp=${rest%%\?*}; hostpart=${hp%%/*}
  case "$hostpart" in
  *@*)
    user=${hostpart%%@*}; hostport=${hostpart##*@}
    case "$user" in *:*) echo "target connection secret: the DB URI must be password-free; the password belongs in the PW key, or use uriSecretRef" >&2; exit 1 ;; esac
    [ "$user@$hostport" = "$hostpart" ] || { echo "target connection secret: unparseable userinfo in the DB URI; use uriSecretRef" >&2; exit 1; }
    ;;
  *)
    user=${PGM_TARGET_USER-}
    [ -n "$user" ] || { echo "target connection secret: no user in the DB URI and the username key is empty" >&2; exit 1; }
    case "$user" in *@*|*:*|*/*|*"?"*|*"#"*|*%*|*"&"*) echo "target connection secret: the username key holds URI syntax; use uriSecretRef for such values" >&2; exit 1 ;; esac
    hostport=$hostpart
    uri="postgresql://$user@$rest"
    ;;
  esac
  case "$user$hostport" in *%*) echo "target connection secret: percent-encoded user or host in the DB URI never matches the passfile; use plain values or uriSecretRef" >&2; exit 1 ;; esac
  ;;
*)
  host=${PGM_TARGET_HOST-}; user=${PGM_TARGET_USER-}
  [ -n "$host" ] || { echo "target connection secret: url key empty and DB is not a URI" >&2; exit 1; }
  [ -n "$user" ] || { echo "target connection secret: username key empty and DB is not a URI" >&2; exit 1; }
  case "$user" in *@*|*:*|*/*|*"?"*|*"#"*|*%*|*"&"*) echo "target connection secret: the username key holds URI syntax; use uriSecretRef for such values" >&2; exit 1 ;; esac
  case "$db" in *@*|*:*|*/*|*"?"*|*"#"*|*%*|*"&"*) echo "target connection secret: the database key holds URI syntax; use uriSecretRef for such values" >&2; exit 1 ;; esac
  case "$host" in *@*|*/*|*"?"*|*"#"*|*%*|*"&"*) echo "target connection secret: the url key holds URI syntax; use uriSecretRef for such values" >&2; exit 1 ;; esac
  case "$host" in *:*) hostport=$host ;; *) hostport=$host:5432 ;; esac
  uri="postgresql://$user@$hostport/$db"
  ;;
esac
host=${hostport%%:*}
case "$uri" in *[?\&]) uri=${uri%?} ;; esac
case "$uri" in *"?keepalives="*|*"&keepalives="*) ;; *\?*) uri="$uri&keepalives=1" ;; *) uri="$uri?keepalives=1" ;; esac
case "$uri" in *"?keepalives_idle="*|*"&keepalives_idle="*) ;; *\?*) uri="$uri&keepalives_idle=10" ;; *) uri="$uri?keepalives_idle=10" ;; esac
case "$uri" in *"?keepalives_interval="*|*"&keepalives_interval="*) ;; *\?*) uri="$uri&keepalives_interval=10" ;; *) uri="$uri?keepalives_interval=10" ;; esac
case "$uri" in *"?keepalives_count="*|*"&keepalives_count="*) ;; *\?*) uri="$uri&keepalives_count=6" ;; *) uri="$uri?keepalives_count=6" ;; esac
export PGCOPYDB_TARGET_PGURI="$uri"
printf '%s' "$uri" > /tmp/pgm-target-uri
[ -f /etc/pgcopydb/creds/target-mnt/target-password ] || { echo "target connection secret: password key PW missing" >&2; exit 1; }
printf '%s:*:*:%s:%s\n' "$(pf_esc "$host")" "$(pf_esc "$user")" "$(pf_esc "$(cat /etc/pgcopydb/creds/target-mnt/target-password)")" >> /tmp/pgpass
export PGPASSFILE=/tmp/pgpass
exec "$0" "$@"
